             (host_result, network_result)
         };
         Action {
             precondition: |input: (BuiltinControllerChoice, ObjectRef), s: ClusterState| {
                 &&& result(input, s).0.is_Enabled()
                 &&& result(input, s).1.is_Enabled()
             },
